    `</tr></thead>`;
  const body = "<tbody>" + g.rows.slice(0, shown).map((row) => {
    const hStyle = RM.rowH[row.row] ? ` style="height:${RM.rowH[row.row]}px"` : "";
    return `<tr${hStyle}><th class="rownum" data-r="${row.row}"><span class="rownum-label">${row.row}</span><span class="row-resize" data-r="${row.row}" title="拖动改行高"></span></th>` +
