// 网格底部"显示更多"控件：默认只渲染前 REGION_RENDER_LIMIT 行，避免整表塞进 DOM。
function updateRegionMore(total, shown) {
  const wrap = document.getElementById("regionGridWrap");
  if (!wrap) return;
  let bar = document.getElementById("regionMore");
  if (shown >= total) { if (bar) bar.remove(); return; }
  if (!bar) { bar = document.createElement("div"); bar.id = "regionMore"; bar.className = "region-more"; wrap.appendChild(bar); }
  bar.innerHTML = `已显示前 ${shown} / 共 ${total} 行 · <button type="button" class="link-btn" id="regionShowAll">显示全部</button>`;
  document.getElementById("regionShowAll").addEventListener("click", () => { RM.showAll = true; renderRegionGrid(); });
}

