function attachRegionEvents(tbl) {
  // 单元格：两步点选（点起点 → 点终点选定）+ 按住拖拽快捷选。
  // mousedown 只记起点；mouseenter 判定拖拽/预览；松手在文档级 onRegionMouseUp 提交（只在 bindRegionModal 绑一次）。
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    cell.addEventListener("mousedown", (ev) => { ev.preventDefault(); SEL.dragStart = { r: +cell.dataset.r, c: +cell.dataset.c }; SEL.dragMoved = false; });
    cell.addEventListener("mouseenter", () => {
      const cur = { r: +cell.dataset.r, c: +cell.dataset.c }; SEL.hover = cur;
      if (SEL.dragStart) { SEL.dragMoved = true; RM.anchor = SEL.dragStart; RM.pending = true; RM.sel = regionRect(SEL.dragStart, cur); paintRegion(); }
      else if (RM.pending && RM.anchor) { RM.sel = regionRect(RM.anchor, cur); paintRegion(); }
      else { showCellFull(cell); }
    });
  });

  // 列宽手柄：拖动改宽，双击自适应
  tbl.querySelectorAll(".col-resize").forEach((h) => {
    h.addEventListener("mousedown", (ev) => startColResize(ev, +h.dataset.c, tbl));
    h.addEventListener("dblclick", (ev) => { ev.stopPropagation(); autoFitCol(+h.dataset.c, tbl); });
    h.addEventListener("click", (ev) => ev.stopPropagation());
  });
  // 行高手柄
  tbl.querySelectorAll(".row-resize").forEach((h) => {
    h.addEventListener("mousedown", (ev) => startRowResize(ev, +h.dataset.r, h));
    h.addEventListener("click", (ev) => ev.stopPropagation());
  });
  // 点列头选整列、点行号选整行（避开手柄）：直接选定并清掉进行中的两步预览
  tbl.querySelectorAll("th.colh").forEach((th) => th.addEventListener("click", (ev) => {
    if (ev.target.classList.contains("col-resize")) return;
    const c = +th.dataset.c, last = RM.grid.n_rows || (RM.grid.rows.length ? RM.grid.rows[RM.grid.rows.length - 1].row : 1);
    RM.sel = { r1: 1, r2: last, c1: c, c2: c }; commitRegionSel();
  }));
  tbl.querySelectorAll("th.rownum").forEach((th) => th.addEventListener("click", (ev) => {
