function regionRect(a, b) { return { r1: Math.min(a.r, b.r), r2: Math.max(a.r, b.r), c1: Math.min(a.c, b.c), c2: Math.max(a.c, b.c) }; }
// 选定：退出预览态、记录为已选定（供 Esc 还原）、刷新高亮与范围框。
function commitRegionSel() {
  RM.pending = false; RM.anchor = null;
  RM.committedSel = RM.sel ? { ...RM.sel } : null;
  paintRegion(); syncRegionInput();
}
// 文档级松手：拖拽完成→选定；纯点击→第一次记起点进入预览，第二次定终点选定。
function onRegionMouseUp() {
  const start = SEL.dragStart, moved = SEL.dragMoved;
  SEL.dragStart = null; SEL.dragMoved = false;
  if (!start) return;
  if (moved) { commitRegionSel(); return; }
  if (RM.pending && RM.anchor) { RM.sel = regionRect(RM.anchor, start); commitRegionSel(); }
  else {
    RM.anchor = start; RM.pending = true; RM.sel = { r1: start.r, r2: start.r, c1: start.c, c2: start.c };
    paintRegion();
    const cell = document.querySelector(`#regionGrid td[data-r="${start.r}"][data-c="${start.c}"]`);
    if (cell) showCellFull(cell);
  }
}
// Esc：取消进行中的两步选择，还原到上次已选定的范围。
function onRegionKey(e) {
  if (e.key !== "Escape" || !RM.pending) return;
  e.stopPropagation();
  RM.pending = false; RM.anchor = null;
  if (RM.committedSel) RM.sel = { ...RM.committedSel };
  paintRegion(); syncRegionInput();
}

